const {phase,data} = $("Phase: tests").item.json;
const status = $json.statusCode;
if ($json.error || status === 429 || status >= 500) return {json: {pause:true}};
if (status !== 200) throw new Error('Unexpected service HTTP status: ' + status);
let payload;
try { payload = JSON.parse($json.body.choices[0].message.content); } catch { payload = {}; }
 data.calls = (data.calls || 0) + 1;
 const out = next => ({json:{phase:data.calls >= (data.callLimit || 12) && ['solve','repair','tests','expand'].includes(next) ? 'needs_review' : next,data}});
// Reviewed deterministic oracle: no candidate source is read here.
function expected(input) {
 const lines = input.endsWith('\n') ? input.slice(0,-1).split('\n') : [];

 const single = lines.length===1 && !input.includes('\r');
 if (['repeat4','python_exact','zen','meow'].includes(data.contract)) {
  if (!single) return null;
  const x=lines[0];
  if(data.contract==='repeat4')return x.repeat(4)+'\n';
  if(data.contract==='python_exact')return (x==='Python'?'ДА':'НЕТ')+'\n';
  if(data.contract==='zen')return (x===''?'ДА':'НЕТ')+'\n';
  return (x.includes('кот')?'МЯУ':'ГАВ')+'\n';
 }
 if(data.contract==='yes_no') {
  if(lines.length!==2 || input.includes('\r')) return null;
  return (lines.every(x=>['да','нет'].includes(x))?'ВЕРНО':'НЕВЕРНО')+'\n';
 }
 if(['xmas','parrot','reverse'].includes(data.contract)) {
  if(lines.length!==3 || input.includes('\r'))return null;
  if(data.contract==='xmas')return (JSON.stringify(lines)===JSON.stringify(['раз','два','три'])?'ГОРИ':'НЕ ГОРИ')+'\n';
  return (data.contract==='reverse'?[...lines].reverse():lines).join('\n')+'\n';
 }
 if(data.contract==='temperature') {
  if(!single || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(lines[0]))return null;
  const n=Number(lines[0]); if(!Number.isFinite(n))return null;
  return (n<15.5?'ХОЛОДНО':n>28?'ЖАРКО':'НОРМАЛЬНО')+'\n';
 }
 if(data.contract==='heights') {
  if(lines.length!==3 || !lines.every(x=>/^[1-9]\d{0,3}$/.test(x)))return null;
  return lines.map(Number).sort((a,b)=>b-a).join('\n')+'\n';
 }

 if(['until_zero','until_nonmultiple','until_empty'].includes(data.contract)) {
  if(!lines.length || input.includes('\r'))return null;
  const prefix=[];
  for(const s of lines){
   if(data.contract!=='until_empty' && !/^(?:0|-?[1-9]\d{0,8})$/.test(s))return null;
   if(data.contract==='until_empty'?s==='':data.contract==='until_zero'?Number(s)===0:Number(s)%10!==0)
    return prefix.map(x=>x+'\n').join('');
   prefix.push(s);
  }
  return null;
 }

 if(data.contract==='xmas2'||data.contract==='xmas3') {
  if(lines.length!==3 || input.includes('\r'))return null;
  const seq=lines.join('\n');
  return (seq==='раз\nдва\nтри'||seq==='1\n2\n3'||(data.contract==='xmas3'&&seq==='один\nдва\nтри')?'ГОРИ':'НЕ ГОРИ')+'\n';
 }

 if(data.contract==='fizzbuzz') {
  if(lines.length!==2 || !lines.every(x=>/^[1-9]\d{0,5}$/.test(x)))return null;
  const [a,b]=lines.map(Number); if(a>=b || b-a>50)return null;
  const result=[]; for(let i=a;i<=b;i++)result.push((i%3===0?'Fizz':'')+(i%5===0?'Buzz':'')||String(i));
  return result.join('\n')+'\n';
 }

 if (data.contract === 'echo' || data.contract === 'length') {
  if (lines.length !== 1 || input.includes('\r')) return null;
  return data.contract === 'echo' ? input : `Слово ${lines[0]} имеет длину ${[...lines[0]].length}\n`;
 }
 if (data.contract === 'leap') {
  if (lines.length!==1 || !/^[1-9]\d{0,5}$/.test(lines[0])) return null;
  const year=Number(lines[0]);
  return (year%400===0 || (year%4===0 && year%100!==0) ? 'Високосный' : 'Не високосный')+'\n';
 }
 if (data.contract === 'sum') {
  if (lines.length !== 2 || !lines.every(x => /^[+-]?\d{1,30}$/.test(x))) return null;
  return String(BigInt(lines[0])+BigInt(lines[1]))+'\n';
 }
 if (data.contract === 'parity') {
  if (lines.length !== 1 || !/^[+-]?\d{1,30}$/.test(lines[0])) return null;
  return BigInt(lines[0])%2n === 0n ? 'чётное\n' : 'нечётное\n';
 }
 if (data.contract === 'sign') {
  if (lines.length !== 1 || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(lines[0])) return null;
  const n=Number(lines[0]); if (!Number.isFinite(n) || Math.abs(n)>1e100) return null;
  return (n>0?'+':n<0?'-':'0')+'\n';
 }
 throw new Error('Unsupported reviewed contract');
}
const cases=data.cases || [], seen=new Set(cases.map(c=>c.input));
const proposals = [...(phase === 'expand' ? data.targetedCases || [] : []), ...(Array.isArray(payload?.cases)?payload.cases.slice(0,16):[])];
for (const c of proposals) {
 if (typeof c?.input !== 'string' || c.input.length>256 || typeof c.output !== 'string' ||
     expected(c.input) !== c.output || seen.has(c.input) ||
     data.examples.some(e=>e.input===c.input) || cases.length>=16) continue;
 cases.push({input:c.input,output:c.output});seen.add(c.input);
}
data.cases=cases;
return out(cases.length<3?phase:'public');

